def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    total_shares = v1 + v2
    return {
        "value": total_shares,
        "trace": {
            "v1": v1,
            "v2": v2,
            "total_shares": total_shares,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "shares"
            }
        }
    }
